module old022::model_compute;
import "std/model.nex" as model;import "std/compute.nex" as compute;import "std/device.nex" as device;
fn answer()->i64{
 assert(model::is_sha256("aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"));
 let tensor:compute::Tensor=unwrap(compute::from_i32([1],[44]));
 assert(unwrap(compute::to_i32(tensor))==[44]);return 44;
}
fn main()->unit !{io}{print(answer());}
test fn retained_answer()->unit{assert(answer()==44);}
